def transform(grid):
    # Downsample each 3x3 tile to its non-background color; background is 0/5.
    out = []
    for br in range(0, len(grid), 3):
        row = []
        for bc in range(0, len(grid[0]), 3):
            counts = {}
            for r in range(br, min(br + 3, len(grid))):
                for c in range(bc, min(bc + 3, len(grid[0]))):
                    v = grid[r][c]
                    if v not in (0, 5):
                        counts[v] = counts.get(v, 0) + 1
            row.append(max(counts, key=counts.get) if counts else 0)
        out.append(row)
    return out

